-- Materialized view: project_hazard_proximity
-- Pairwise project<->hazard distances in meters (geography), capped at
-- 10000 m.  Scenario buffers filter on distance_m at query time.
CREATE MATERIALIZED VIEW project_hazard_proximity AS
SELECT
    p.id AS project_id,
    h.id AS hazard_id,
    h.type AS hazard_type,
    h.severity,
    ST_Distance(p.geometry::geography, h.geometry::geography) AS distance_m
FROM projects p
JOIN hazards h
    ON ST_DWithin(p.geometry::geography, h.geometry::geography, 10000);

-- Materialized view: project_constraint_proximity
CREATE MATERIALIZED VIEW project_constraint_proximity AS
SELECT
    p.id AS project_id,
    c.id AS constraint_id,
    c.type AS constraint_type,
    ST_Distance(p.geometry::geography, c.geometry::geography) AS distance_m
FROM projects p
JOIN constraints c
    ON ST_DWithin(p.geometry::geography, c.geometry::geography, 10000);

-- Refresh statements (single source of truth: app/analytics/queries.py;
-- executed via app.db.maintenance.refresh_analytics_views)
